"""
Decomposer — orchestrates classification, dimension selection, and micro-query
generation. Checks local KB first via AtomicResolver. Zero LLM calls.
"""

from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

from .dimension_registry import Dimension, get_dimensions
from .micro_query_generator import MicroQuery, MicroQueryGenerator
from .query_classifier import ClassificationResult, QueryClassifier
from ..reasoning.problem_decomposer import AtomicQuestion
from ..reasoning.atomic_resolver import AtomicResolver


@dataclass
class DecompositionTree:
    original_query: str
    query_type: str
    classification_confidence: float
    dimensions: list[Dimension]
    micro_queries: list[MicroQuery]
    pre_resolved: list[dict] = field(default_factory=list)
    context: dict = field(default_factory=dict)

    @property
    def queries_to_fire(self) -> list[MicroQuery]:
        resolved_texts = {r["query"] for r in self.pre_resolved}
        return [q for q in self.micro_queries if q.text not in resolved_texts]

    @property
    def total_queries(self) -> int:
        return len(self.micro_queries)

    @property
    def cached_count(self) -> int:
        return len(self.pre_resolved)

    def to_dict(self) -> dict:
        return {
            "original_query": self.original_query,
            "query_type": self.query_type,
            "classification_confidence": self.classification_confidence,
            "dimensions": [d.to_dict() for d in self.dimensions],
            "micro_queries": [q.to_dict() for q in self.micro_queries],
            "pre_resolved": self.pre_resolved,
            "context": self.context,
            "total_queries": self.total_queries,
            "cached_count": self.cached_count,
            "queries_to_fire": len(self.queries_to_fire),
        }


class Decomposer:
    def __init__(self, resolver: Optional[AtomicResolver] = None, weight_overrides: Optional[dict[str, float]] = None):
        self.classifier = QueryClassifier()
        self.generator = MicroQueryGenerator()
        self.resolver = resolver
        self.weight_overrides = weight_overrides

    def decompose(self, query: Optional[str]) -> DecompositionTree:
        if not query or not query.strip():
            return DecompositionTree(
                original_query=query or "",
                query_type="custom",
                classification_confidence=0.0,
                dimensions=[],
                micro_queries=[],
                context={},
            )

        classification = self.classifier.classify(query)
        dimensions = get_dimensions(classification.query_type, weight_overrides=self.weight_overrides)
        micro_queries = self.generator.generate_batch(dimensions, classification.context)

        pre_resolved = []
        if self.resolver:
            pre_resolved = self._resolve_against_kb(micro_queries, classification.context)

"""
MicroQueryRunner — fires micro-queries to LLM via injectable research_fn.
Enforces single-fact JSON responses. LLM = search engine only.
"""

import json
import time
from dataclasses import dataclass, field
from typing import Callable, Optional

from .micro_query_generator import MicroQuery

MICRO_FACT_PROMPT = """Answer this factual question with a SINGLE data point.
Format: {{"fact": "...", "value": "...", "confidence": 0.0-1.0, "source": "...", "date": "YYYY-MM-DD"}}

Question: {question}
Expected answer type: {expected_type}

Rules:
- ONE fact only. No reasoning, no explanation, no context.
- If you don't know, return {{"fact": null, "confidence": 0.0}}
- Include source URL or publication name if available."""

BATCH_SIZE = 5
BATCH_DELAY_S = 1.0


@dataclass
class MicroQueryResult:
    query: MicroQuery
    raw_response: str
    parsed_fact: Optional[dict] = None
    parse_success: bool = False

    def to_dict(self) -> dict:
        return {
            "query": self.query.to_dict(),
            "raw_response": self.raw_response[:500],
            "parsed_fact": self.parsed_fact,
            "parse_success": self.parse_success,
        }


@dataclass
class RunnerStats:
    queries_fired: int = 0
    responses_received: int = 0
    parse_successes: int = 0
    parse_failures: int = 0

    def to_dict(self) -> dict:
        return {
            "queries_fired": self.queries_fired,
            "responses_received": self.responses_received,
            "parse_successes": self.parse_successes,
            "parse_failures": self.parse_failures,
            "parse_success_rate": round(
                self.parse_successes / max(self.responses_received, 1), 3
            ),
        }


class MicroQueryRunner:
    def __init__(
        self,
        research_fn: Callable[[str], str],
        batch_size: int = BATCH_SIZE,
        batch_delay: float = BATCH_DELAY_S,
    ):
        self.research_fn = research_fn
        self.batch_size = batch_size
        self.batch_delay = batch_delay

    def run_batch(self, queries: list[MicroQuery]) -> tuple[list[MicroQueryResult], RunnerStats]:
        results: list[MicroQueryResult] = []
        stats = RunnerStats()

        for i in range(0, len(queries), self.batch_size):
            batch = queries[i : i + self.batch_size]

            if i > 0 and self.batch_delay > 0:
                time.sleep(self.batch_delay)

            for query in batch:
                result = self._run_single(query)
                results.append(result)
                stats.queries_fired += 1
                if result.raw_response:
                    stats.responses_received += 1
                if result.parse_success:
                    stats.parse_successes += 1
                else:
                    stats.parse_failures += 1

        return results, stats

    def _run_single(self, query: MicroQuery) -> MicroQueryResult:
        prompt = MICRO_FACT_PROMPT.format(
            question=query.text,
            expected_type=query.expected_type,
        )

        try:
            raw = self.research_fn(prompt)
        except Exception:
            return MicroQueryResult(query=query, raw_response="")

        parsed = self._parse_response(raw)
        if parsed:
            return MicroQueryResult(
                query=query,
                raw_response=raw,
                parsed_fact=parsed,
                parse_success=True,
            )

        # Fallback: try prose extraction
        parsed = self._parse_prose_fallback(raw, query)
        return MicroQueryResult(
            query=query,
            raw_response=raw,
            parsed_fact=parsed,
            parse_success=parsed is not None,
        )

    def _parse_response(self, raw: str) -> Optional[dict]:
        if not raw:
            return None
        text = raw.strip()
        # Find JSON in response
        start = text.find("{")
        end = text.rfind("}") + 1
        if start < 0 or end <= start:
            return None
        try:
            data = json.loads(text[start:end])
        except json.JSONDecodeError:
            return None

        if "fact" not in data:
            return None
        if data["fact"] is None:
            return None

        return {
            "fact": str(data["fact"]),
            "value": data.get("value"),
            "confidence": float(data.get("confidence", 0.5)),
            "source": data.get("source"),
            "date": data.get("date"),
        }

    def _parse_prose_fallback(self, raw: str, query: MicroQuery) -> Optional[dict]:
        if not raw or len(raw.strip()) < 10:
            return None
        text = raw.strip()
        if len(text) > 500:
            text = text[:500]
        return {
            "fact": text,
            "value": None,
            "confidence": max(0.0, 0.4),
            "source": "prose_extraction",
            "date": None,
        }

