"""
DimensionScorer — scores each dimension based on fact coverage and confidence.
Pure LOCAL computation, zero LLM calls.
"""

from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional

from ..hunger.claim_parser import ParsedClaim


@dataclass
class DimensionScore:
    dimension: str
    score: float
    fact_count: int
    avg_confidence: float
    contradictions: int
    zone_tag: str

    def to_dict(self) -> dict:
        return {
            "dimension": self.dimension,
            "score": round(self.score, 3),
            "fact_count": self.fact_count,
            "avg_confidence": round(self.avg_confidence, 3),
            "contradictions": self.contradictions,
            "zone_tag": self.zone_tag,
        }


FACTS_NORM_CAP = 5
FRESHNESS_DAYS = 180


class DimensionScorer:
    def score(self, dimension: str, facts: list[ParsedClaim]) -> DimensionScore:
        if not facts:
            return DimensionScore(
                dimension=dimension, score=0.0, fact_count=0,
                avg_confidence=0.0, contradictions=0, zone_tag="?",
            )

        fact_count = len(facts)
        fact_count_norm = min(fact_count / FACTS_NORM_CAP, 1.0)
        avg_confidence = sum(f.confidence for f in facts) / fact_count
        contradictions = sum(1 for f in facts if f.zone_tag == "?")
        contradiction_penalty = contradictions / fact_count if fact_count > 0 else 0.0
        freshness_bonus = self._calc_freshness(facts)

        score = (
            fact_count_norm * 0.3
            + avg_confidence * 0.4
            - contradiction_penalty * 0.2
            + freshness_bonus * 0.1
        )
        score = max(0.0, min(1.0, score))

        if score >= 0.75:
            zone_tag = "K"
        elif score >= 0.5:
            zone_tag = "T"
        else:
            zone_tag = "?"

        return DimensionScore(
            dimension=dimension,
            score=score,
            fact_count=fact_count,
            avg_confidence=avg_confidence,
            contradictions=contradictions,
            zone_tag=zone_tag,
        )

    def score_all(self, facts_by_dimension: dict[str, list[ParsedClaim]]) -> dict[str, DimensionScore]:
        return {dim: self.score(dim, facts) for dim, facts in facts_by_dimension.items()}

    def _calc_freshness(self, facts: list[ParsedClaim]) -> float:
        fresh_count = 0
        dated_count = 0
        now = datetime.now(timezone.utc)
        for f in facts:
            if not f.source_date:
                continue
            try:
                dt = datetime.strptime(f.source_date[:10], "%Y-%m-%d").replace(tzinfo=timezone.utc)
                dated_count += 1
                if (now - dt).days <= FRESHNESS_DAYS:
                    fresh_count += 1
            except ValueError:
                continue
        if dated_count == 0:
            return 0.5
        return fresh_count / dated_count
